import { VendorWorkspace } from '@/components/supply/vendors';

/**
 * 6.1.1.1 供应商列表。
 *
 * <p>蓝图：「维护供应商档案清单：编码、名称、联系方式、合作状态、供货 SKU 数、
 * 采购金额累计、准时交付率、质量合格率，支持筛选与导出。」
 *
 * <p>🔴 页面顶部那句话不是提示语，是这一页的设计前提：**供应商数据主数据在 03，
 * 本模块呈现采购视角的视图与运营动作，避免同一实体两处可编辑**。
 * 所以表格里的编码 / 名称 / 联系方式 / 合作等级 / 主体状态全部只读，页面上没有任何
 * 编辑它们的入口 —— 它们要回往来单位档案（/partners）改。本页只维护采购侧的
 * 合作状态、主供类目，以及到货 / 质检这两张只追加的事实表。
 *
 * <p>四个关键指标（供货 SKU 数、采购金额累计、准时交付率、质量合格率）全部是
 * 列表查询里的 SQL 聚合，没有一个是存下来的字段；准时率与合格率是**有时间窗**的统计，
 * 页面上必须显示当前生效的窗口 —— 一个不说清是哪一段的「准时率 96%」在供应商评审里没有意义。
 */
export default function VendorsPage() {
  return <VendorWorkspace />;
}
